module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,
    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

    reg [1:0] counter;
    reg [9:0] accum_register;
    reg valid_latch;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            counter <= 2'b00;
            accum_register <= 10'b0;
            valid_out <= 1'b0;
            valid_latch <= 1'b0;
        end
        else begin
            if (valid_in) begin
                counter <= counter + 1;
                accum_register <= accum_register + data_in;
            end

            if (counter == 2'b11 && ~valid_latch) begin
                data_out <= accum_register;
                valid_out <= 1'b1;
                valid_latch <= 1'b1;
            end
            else begin
                valid_out <= 1'b0;
                valid_latch <= 1'b0;
            end

            if (counter == 2'b11) begin
                counter <= 2'b00;
                accum_register <= 10'b0;
            end
        end
    end

endmodule

