module adder_32bit(
    input [32:1] A,
    input [32:1] B,
    output [32:1] S,
    output C32
);

    wire [16:1] P;
    wire [16:1] G;
    wire [16:1] C16;

    // Instantiate lower 16-bit CLA block
    cla_16bit cla_lower(
        .A(A[16:1]),
        .B(B[16:1]),
        .P(P),
        .G(G),
        .C(C16)
    );

    // Instantiate upper 16-bit CLA block
    cla_16bit cla_upper(
        .A(A[32:17]),
        .B(B[32:17]),
        .P({G[16], G[15]}),
        .G({A[16], B[16]}),
        .C(C32)
    );

    assign S = {cla_upper.S, cla_lower.S};

endmodule

module adder_32bit(
