    wire [16:1] C16;

    // First 16-bit CLA block
    CLA_16bit CLA1(.A(A[16:1]), .B(B[16:1]), .P(P), .G(G), .Cout(C16), .S(S[16:1]));

    // Second 16-bit CLA block
    CLA_16bit CLA2(.A(A[32:17]), .B(B[32:17]), .P(P), .G(G), .Cin(C16), .S(S[32:17]));

    assign S = {S[32:17], S[16:1]};
