    output [32:1] S,
    output C32
);

    wire [16:1] P0, G0, P1, G1;
    wire C16;

    // Instantiate 16-bit CLA block for lower 16 bits
    cla_16bit cla0(.A(A[16:1]), .B(B[16:1]), .P(P0), .G(G0), .C(C16));

    // Generate P and G signals for the upper 16 bits
    assign P1 = G0 | (P0 & A[17]) | (P0 & B[17]);
    assign G1 = A[17] & B[17];

    // Instantiate 16-bit CLA block for upper 16 bits
    cla_16bit cla1(.A(A[32:17]), .B(B[32:17]), .P(P1), .G(G1), .C(C32));

    // Concatenate the results for the 32-bit sum
    assign S = {C32, cla1.S};

