module cla_16bit(
    input [16:1] A,
    input [16:1] B,
    input [16:1] P,
    input [16:1] G,
    output [16:1] S,
    output C
);

    wire [16:1] C_propagate, C_generate;

    // Generate intermediate carry signals
    assign C_propagate[1] = P[1];
    assign C_generate[1] = G[1];

    // Generate C_propagate and C_generate for the remaining bits
    gen_carry: for (int i = 2; i <= 16; i = i + 1) begin
        assign C_propagate[i] = P[i] | (G[i] & C_propagate[i-1]);
        assign C_generate[i] = G[i] & C_propagate[i-1];
    end

    // Calculate the sum for each bit
    assign S = A ^ B ^ C_propagate;

    // Compute the final carry out
    assign C = C_generate[16];

endmodule

module adder_32bit(
    input [32:1] A,
    input [32:1] B,
    output [32:1] S,
    output C32
);

wire [16:1] P1, G1, P2, G2;
wire [16:1] C16;
wire [32:1] S1;

// First 16-bit CLA block
CLA_16bit clablock1(
    .A(A[16:1]),
    .B(B[16:1]),
    .P(P1),
    .G(G1),
    .C(C16),
    .S(S1[16:1])
);

// Second 16-bit CLA block
CLA_16bit clablock2(
    .A(A[32:17]),
    .B(B[32:17]),
    .P(P2),
    .G(G2),
    .C(C32),
    .S(S1[32:17])
);

assign S = {S1[32:17], S1[16:1]};

assign P1 = A[16:1] | B[16:1];
assign G1 = A[16:1] & B[16:1];
assign P2 = A[32:17] | B[32:17] | G1;
assign G2 = A[32:17] & B[32:17] | (A[32:17] & G1) | (B[32:17] & G1);

endmodule

