    cla_16bit cla1(.A(A[16:1]), .B(B[16:1]), .P(P1), .G(G1), .C(C16));
    cla_16bit cla2(.A(A[32:17]), .B(B[32:17]), .P(P2), .G(G2), .C(C_out));

    // Carry calculations for the 32-bit adder
    assign P1 = A[16:1] ^ B[16:1];
    assign G1 = A[16:1] & B[16:1];
    assign P2 = A[32:17] ^ B[32:17];
    assign G2 = A[32:17] & B[32:17];

    // Final sum calculation
    assign S = {C_out[16:1], C16};
    assign C32 = G1 | (P1 & G2);

