        stage0_addb <= 0;
        stage0_i_en <= 0;
    end else begin
        stage0_adda <= adda;
        stage0_addb <= addb;
        stage0_i_en <= i_en;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        stage1_adda <= 0;
        stage1_addb <= 0;
        stage1_i_en <= 0;
    end else begin
        stage1_adda <= stage0_sum[DATA_WIDTH-1:0];
        stage1_addb <= {1'b0, stage0_sum[DATA_WIDTH]};
        stage1_i_en <= stage0_i_en;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        stage2_adda <= 0;
        stage2_addb <= 0;
        stage2_i_en <= 0;
    end else begin
        stage2_adda <= stage1_sum[DATA_WIDTH-1:0];
        stage2_addb <= {1'b0, stage1_sum[DATA_WIDTH]};
        stage2_i_en <= stage1_i_en;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        stage3_adda <= 0;
        stage3_addb <= 0;
        stage3_i_en <= 0;
    end else begin
        stage3_adda <= stage2_sum[DATA_WIDTH-1:0];
        stage3_addb <= {1'b0, stage2_sum[DATA_WIDTH]};
        stage3_i_en <= stage2_i_en;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        stage0_sum <= 0;
    end else begin
        stage0_sum <= (stage0_i_en) ? (stage0_adda + stage0_addb) : 0;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        stage1_sum <= 0;
    end else begin
        stage1_sum <= (stage1_i_en) ? (stage1_adda + stage1_addb) : 0;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        stage2_sum <= 0;
