);

reg [DATA_WIDTH-1:0] adda_reg;
reg [DATA_WIDTH-1:0] addb_reg;
reg i_en_reg;
reg [DATA_WIDTH:0] sum_reg;
reg [DATA_WIDTH:1] carry_reg;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg <= 0;
        addb_reg <= 0;
        i_en_reg <= 0;
        sum_reg <= 0;
        carry_reg <= 0;
        o_en <= 0;
    end else begin
        adda_reg <= adda;
        addb_reg <= addb;
        i_en_reg <= i_en;
        sum_reg <= sum_reg + {1'b0, adda_reg} + {1'b0, addb_reg} + carry_reg;
        carry_reg <= sum_reg[DATA_WIDTH+1];
        o_en <= i_en_reg;
    end
end

assign result = sum_reg;

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
