reg [DATA_WIDTH-1:0] stage1_adda, stage1_addb;
reg [DATA_WIDTH-1:0] stage2_adda, stage2_addb;
reg [DATA_WIDTH-1:0] stage3_adda, stage3_addb;

reg [DATA_WIDTH:0] stage0_sum, stage1_sum, stage2_sum, stage3_sum;
reg [DATA_WIDTH:1] carry0, carry1, carry2;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        stage0_adda <= 0;
        stage0_addb <= 0;
        stage1_adda <= 0;
        stage1_addb <= 0;
        stage2_adda <= 0;
        stage2_addb <= 0;
        stage3_adda <= 0;
        stage3_addb <= 0;

        stage0_sum <= 0;
        stage1_sum <= 0;
        stage2_sum <= 0;
        stage3_sum <= 0;

        carry0 <= 0;
        carry1 <= 0;
        carry2 <= 0;

        o_en <= 0;
    end else begin
        stage0_adda <= adda;
        stage0_addb <= addb;
        stage1_adda <= stage0_sum[DATA_WIDTH-1:0];
        stage1_addb <= stage0_sum[DATA_WIDTH:DATA_WIDTH-1];
        stage2_adda <= stage1_sum[DATA_WIDTH-1:0];
        stage2_addb <= stage1_sum[DATA_WIDTH:DATA_WIDTH-1];
        stage3_adda <= stage2_sum[DATA_WIDTH-1:0];
        stage3_addb <= stage2_sum[DATA_WIDTH:DATA_WIDTH-1];

        stage0_sum <= {carry0, stage0_adda} + {carry0, stage0_addb};
        stage1_sum <= {carry1, stage1_adda} + {carry1, stage1_addb};
        stage2_sum <= {carry2, stage2_adda} + {carry2, stage2_addb};
        stage3_sum <= {carry2, stage3_adda} + {carry2, stage3_addb};

        carry0 <= stage0_sum[DATA_WIDTH];
        carry1 <= stage1_sum[DATA_WIDTH];
        carry2 <= stage2_sum[DATA_WIDTH];

        o_en <= i_en;
    end
end

assign result = stage3_sum;

endmodule

