        sum_reg[1] <= 0;
        sum_reg[2] <= 0;
        sum_reg[3] <= 0;
        result_reg <= 0;
        o_en <= 0;
    end else begin
        a_reg <= i_en ? adda : a_reg;
        b_reg <= i_en ? addb : b_reg;
        sum_reg[0] <= i_en ? a_reg + b_reg : sum_reg[0];
        sum_reg[1] <= sum_reg[0];
        sum_reg[2] <= sum_reg[1];
        sum_reg[3] <= sum_reg[2];
        result_reg <= i_en ? sum_reg[3] : result_reg;
        o_en <= i_en;
    end
end

assign result = result_reg;

endmodule

