    output reg o_en
);

reg [DATA_WIDTH-1:0] adda_reg;
reg [DATA_WIDTH-1:0] addb_reg;
reg [DATA_WIDTH-1:0] sum_reg1, sum_reg2, sum_reg3, sum_reg4;
reg carry_reg1, carry_reg2, carry_reg3;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        adda_reg <= 0;
        addb_reg <= 0;
        sum_reg1 <= 0;
        sum_reg2 <= 0;
        sum_reg3 <= 0;
        sum_reg4 <= 0;
        carry_reg1 <= 0;
        carry_reg2 <= 0;
        carry_reg3 <= 0;
        o_en <= 0;
    end else begin
        adda_reg <= i_en ? adda : adda_reg;
        addb_reg <= i_en ? addb : addb_reg;

        // Stage 1
        {carry_reg1, sum_reg1} <= adda_reg + addb_reg;

        // Stage 2
        {carry_reg2, sum_reg2} <= {carry_reg1, sum_reg1} + {STG_WIDTH{carry_reg1}};

        // Stage 3
        {carry_reg3, sum_reg3} <= {carry_reg2, sum_reg2} + {STG_WIDTH{carry_reg2}};

        // Stage 4
        {carry_reg3, sum_reg4} <= {carry_reg3, sum_reg3} + {STG_WIDTH{carry_reg3}};

        o_en <= 1;
    end
end

assign result = {carry_reg3, sum_reg4};

endmodule

