// Asynchronous FIFO module
module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk, rclk,
    input wrstn, rrstn,
    input winc, rinc,
    input [WIDTH-1:0] wdata,
    output reg wfull, rempty,
    output reg [WIDTH-1:0] rdata
);
    // Binary pointers
    reg [$clog2(DEPTH)-1:0] waddr_bin, raddr_bin;
    reg [$clog2(DEPTH)-1:0] waddr_sync, raddr_sync;

    // Gray-coded pointers
    reg [$clog2(DEPTH):0] wptr, rptr;
    reg [$clog2(DEPTH):0] wptr_buff, rptr_buff;

    // Dual-port RAM instantiation
    dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) RAM (
        .wclk(wclk),
        .rclk(rclk),
        .wenc(winc),
        .renc(rinc),
        .waddr(waddr_bin),
        .wdata(wdata),
        .raddr(raddr_bin),
        .rdata(rdata)
    );

    // Write Pointer Increment
    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn)
            waddr_bin <= 0;
        else if (winc)
            waddr_bin <= waddr_bin + 1;
    end

    // Write Pointer Gray Encoding
    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn)
            wptr <= 0;
        else
            wptr <= (waddr_bin >> 1) ^ waddr_bin;  // Binary-to-Gray
    end

    // Read Pointer Increment
    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn)
            raddr_bin <= 0;
        else if (rinc)
            raddr_bin <= raddr_bin + 1;
    end

    // Read Pointer Gray Encoding
    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn)
            rptr <= 0;
        else
            rptr <= (raddr_bin >> 1) ^ raddr_bin;  // Binary-to-Gray
    end

    // Synchronize Write Pointer into Read Clock Domain
    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn)
            wptr_buff <= 0;
        else
            wptr_buff <= wptr;
    end

    // Synchronize Read Pointer into Write Clock Domain
    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn)
            rptr_buff <= 0;
        else
            rptr_buff <= rptr;
    end

    // Full Signal Calculation
    always @(*) begin
        wfull = (wptr == {~rptr_sync[$clog2(DEPTH):$clog2(DEPTH)-1], rptr_sync[$clog2(DEPTH)-2:0]});
    end

    // Empty Signal Calculation
    always @(*) begin
        rempty = (wptr_sync == rptr);
    end
endmodule

