    reg [2:0] cnt_10, cnt_100;

    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_10 <= 3'b0;
            cnt_100 <= 3'b0;
            CLK_50 <= 1'b0;
            CLK_10 <= 1'b0;
            CLK_1 <= 1'b0;
        end else begin
            // CLK_50 generation
            CLK_50 <= ~CLK_50;

            // CLK_10 generation
            if (cnt_10 == 3'b100) begin
                cnt_10 <= 3'b0;
                CLK_10 <= ~CLK_10;
            end else begin
                cnt_10 <= cnt_10 + 1;
            end

            // CLK_1 generation
            if (cnt_100 == 6'b110001) begin
                cnt_100 <= 6'b0;
                CLK_1 <= ~CLK_1;
            end else begin
                cnt_100 <= cnt_100 + 1;
            end
        end
    end
