         // Booth algorithm operations
         if (ctr < 5) begin
            {multiplier, multiplicand[7]} <= {1'b0, multiplier[15:1], multiplicand[7:1]};
            ctr <= ctr + 1;
         end else begin
            rdy <= 1'b1;
         end
      end
   end
endmodule

