	if (~rst_n) begin
		partial_sums[0] <= 8'b0;
		partial_sums[1] <= 8'b0;
	end
	else begin
		partial_sums[0] <= partial_products[0] ? mul_b : 8'b0;
		partial_sums[1] <= partial_products[1] ? mul_b : 8'b0;
	end
end

always @(posedge clk or negedge rst_n) begin
	if (~rst_n) begin
