		end
	end else begin
		for (int i = 0; i < size; i = i + 1) begin
			partial_products[i] <= (partial_products[i] << 1) + (mul_a & (1 << i) ? mul_b : 0);
			partial_sums[0] <= partial_products[i] + partial_sums[0];
			partial_sums[1] <= partial_sums[0] + partial_sums[1];
