always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= 2'b00;
        data_out <= 1'b0;
    end
    else begin
        case (state)
            2'b00: begin
                if (data_in == 1)
                    state <= 2'b01;
            end
            2'b01: begin
                if (data_in == 0)
                    state <= 2'b10;
                else
                    state <= 2'b00;
            end
            2'b10: begin
                if (data_in == 0)
                    state <= 2'b00;
                else
                    state <= 2'b10;
            end
        endcase

        if (state == 2'b10)
            data_out <= 1'b1;
        else
