module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
    );
    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] r;
    reg zero, carry, negative, overflow, flag;
    reg [31:0] res;
    reg [31:0] signed_a, signed_b;
    reg [31:0] shift_amount;

    always @(*) begin
        signed_a = $signed(a);
        signed_b = $signed(b);

        case(aluc)
            ADD: begin
                res = signed_a + signed_b;
                carry = res[32];
                overflow = (signed_a[31] == signed_b[31]) && (res[31] != signed_a[31]);
                flag = (signed_a < signed_b) ? 1'b1 : 1'b0;
            end
            ADDU: begin
                res = a + b;
                carry = res[32];
            end
            SUB: begin
                res = signed_a - signed_b;
                carry = res[32];
                overflow = (signed_a[31] != signed_b[31]) && (res[31] != signed_a[31]);
                flag = (signed_a < signed_b) ? 1'b1 : 1'b0;
            end
            SUBU: begin
                res = a - b;
                carry = res[32];
            end
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: res = (signed_a < signed_b) ? 32'b1 : 32'b0;
            SLTU: res = (a < b) ? 32'b1 : 32'b0;
            SLL: res = a << 1;
            SRL: res = a >> 1;
            SRA: res = $signed(a) >>> 1;
            SLLV: res = a << b[4:0];
            SRLV: res = a >> b[4:0];
            SRAV: res = $signed(a) >>> b[4:0];
            LUI: res = {b, 16'b0};
            default: res = 32'bz;
        endcase

        zero = (res == 32'b0) ? 1'b1 : 1'b0;
        negative = res[31];
        r = res;
    end
endmodule

module alu(
    input [31:0] a,
