    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] r;
    reg zero, carry, negative, overflow, flag;
    reg [31:0] res;
    wire [31:0] signed_a, signed_b;
    wire [4:0] shift_amount;

    always @(*) begin
        signed_a = (a[31]) ? {{27{1'b1}}, a[31:0]} : a;
        signed_b = (b[31]) ? {{27{1'b1}}, b[31:0]} : b;

        case(aluc)
            ADD: res = signed_a + signed_b;
            ADDU: res = a + b;
            SUB: res = signed_a - signed_b;
            SUBU: res = a - b;
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: res = (signed_a < signed_b) ? 32'b1 : 32'b0;
            SLTU: res = (a < b) ? 32'b1 : 32'b0;
            SLL: res = a << b[4:0];
            SRL: res = a >> b[4:0];
            SRA: res = (a[31] == 1) ? {{b[4:0], a[31]}, a[31:5]} : a >> b[4:0];
            SLLV: res = a << b[4:0];
            SRLV: res = a >> b[4:0];
            SRAV: res = (a[31] == 1) ? {{b[4:0], a[31]}, a[31:5]} : a >> b[4:0];
            LUI: res = {b, 16'b0};
            default: res = 32'bz;
        endcase

        zero = (res == 32'b0) ? 1 : 0;
        negative = res[31];

        if(aluc == ADD || aluc == ADDU) begin
            carry = (res < a) ? 1 : 0;
            overflow = ((a[31] == b[31]) && (res[31] != a[31])) ? 1 : 0;
        end else if(aluc == SUB || aluc == SUBU) begin
            carry = (a < b) ? 1 : 0;
            overflow = ((a[31] != b[31]) && (res[31] != a[31])) ? 1 : 0;
        end else begin
            carry = 0;
            overflow = 0;
        end

        flag = res[31];
        r = res;
    end
endmodule

